%%% Compute the target contribution in each 128 x 128 cell generated by the simulation.
%%% Process: For each cell, generate the simulated mWidar signal. Look a window around where the target is an multiply the signal intensity in each cell in that window
%%% Result: A 128 x 128 lookup table of likely target intensities for targets in those cells.
%%% Things to look at after the result: Variance in signal intensities, size of window (defualt 5)

addpath('TBD/Includes')

s = simulator();
p_window = 5; %%% Define the size of the square window we are looking at

L = zeros(128,128); % Store like in here

for i = 1:128 % rows
    i
    for j = 1:128 % cols
        pos = {[j, i]};
        % Generate the signal
        h = s.generate_mWidar_image(pos, 'pixels', true);
        h = h(:); % make into col vector
        score = norm(h)^2;
        L(i,j) = score;
    end
end

save('TBD/supp/TargetContribution.mat', "L")
var(L(:))